    row.createEl("label", { text: "Folder" });
    this.inputEl = row.createEl("input", {
      cls: "nameforge-modal__pack-name-input",
      attr: {
        type: "text",
        placeholder: DEFAULT_NAMES_FOLDER,
        value: this.currentPath || DEFAULT_NAMES_FOLDER
      }
    });
    this.inputEl.focus();
